.motion-sample {
  --ml-accent: #c6f66b;
  --ml-ink: #13210d;
  box-sizing: border-box;
  position: relative;
  display: grid;
  place-items: center;
  width: 104px;
  height: 68px;
  border-radius: 10px;
  color: var(--ml-ink);
  background: var(--ml-accent);
  font: 700 20px/1 system-ui, sans-serif;
}

@keyframes ml-kinetic-tracking {
  0%, 12% { letter-spacing: .42em; opacity: 0; transform: scale(.93); }
  55%, 87% { letter-spacing: .02em; opacity: 1; transform: scale(1); }
  100% { letter-spacing: -.05em; opacity: 0; transform: scale(1.04); }
}
.motion-sample { width: 132px; background: transparent; color: var(--ml-accent); white-space: nowrap; animation: ml-kinetic-tracking 3.5s cubic-bezier(.16,.66,.26,1) infinite; }

@media (prefers-reduced-motion: reduce) {
  .motion-sample {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
    filter: none !important;
    clip-path: none !important;
    letter-spacing: normal !important;
  }
  .motion-sample::before,
  .motion-sample::after {
    animation: none !important;
    transition: none !important;
  }
}

